<?php require_once __DIR__.'/config/config.php';require_login();$me=current_user_id();$username=trim($_GET['u']??'');if($username!==''){$s=$conn->prepare('SELECT * FROM users WHERE username=?');$s->bind_param('s',$username);}else{$s=$conn->prepare('SELECT * FROM users WHERE id=?');$s->bind_param('i',$me);}$s->execute();$user=$s->get_result()->fetch_assoc();if(!$user){http_response_code(404);exit('RP profile not found.');}$uid=(int)$user['id'];$own=$uid===$me;$error='';
if($own&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$display=trim($_POST['display_name']??'');$bio=trim($_POST['bio']??'');if($display===''||mb_strlen($display)>80||mb_strlen($bio)>500)throw new RuntimeException('Check your display name and bio.');$avatar=save_image($_FILES['avatar']??[],'profiles');$cover=save_image($_FILES['cover']??[],'covers');$sql='UPDATE users SET display_name=?,bio=?';$types='ss';$args=[$display,$bio];if($avatar){$sql.=',avatar_url=?';$types.='s';$args[]=$avatar;}if($cover){$sql.=',cover_url=?';$types.='s';$args[]=$cover;}$sql.=' WHERE id=?';$types.='i';$args[]=$uid;$st=$conn->prepare($sql);$st->bind_param($types,...$args);$st->execute();$_SESSION['display_name']=$display;flash('RP profile updated!');redirect('profile.php');}catch(Throwable $ex){$error=$ex->getMessage();}$s=$conn->prepare('SELECT * FROM users WHERE id=?');$s->bind_param('i',$uid);$s->execute();$user=$s->get_result()->fetch_assoc();}
$fc=$conn->prepare('SELECT COUNT(*) n FROM follows WHERE following_id=?');$fc->bind_param('i',$uid);$fc->execute();$followers=(int)$fc->get_result()->fetch_assoc()['n'];$fc=$conn->prepare('SELECT COUNT(*) n FROM follows WHERE follower_id=?');$fc->bind_param('i',$uid);$fc->execute();$following=(int)$fc->get_result()->fetch_assoc()['n'];$isFollowing=false;if(!$own){$fc=$conn->prepare('SELECT 1 FROM follows WHERE follower_id=? AND following_id=?');$fc->bind_param('ii',$me,$uid);$fc->execute();$isFollowing=(bool)$fc->get_result()->fetch_row();}$st=$conn->prepare('SELECT p.*,u.username,u.display_name,u.avatar_url FROM posts p JOIN users u ON u.id=p.user_id WHERE p.user_id=? ORDER BY p.created_at DESC');$st->bind_param('i',$uid);$st->execute();$posts=$st->get_result();$page_title=$user['display_name'].' RP Profile';require __DIR__.'/includes/header.php';?>
<section class="profile-cover" style="<?=!empty($user['cover_url'])?'background-image:url('.e(BASE_URL.'/'.$user['cover_url']).')':''?>"><span>RPWVERSE PROFILE</span></section><section class="card profile-header"><div class="profile-avatar-large"><?=avatar_html($user['avatar_url'],$user['display_name'])?></div><div class="profile-info"><h1><?=e($user['display_name'])?></h1><p class="muted">@<?=e($user['username'])?> · Member since <?=e(date('M Y',strtotime($user['created_at'])))?></p><p class="bio-text"><?=nl2br(e($user['bio']?:'This member has not added a bio yet.'))?></p><div class="profile-stats"><span><b><?=$followers?></b> Followers</span><span><b><?=$following?></b> Following</span><span><b><?=$posts->num_rows?></b> Public posts</span></div></div><div class="profile-actions"><?php if($own):?><a class="btn" href="#edit-profile">Edit profile</a><?php else:?><form method="post" action="follow.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="user_id" value="<?=(int)$user['id']?>"><button class="btn"><?=$isFollowing?'Following ✓':'Follow +'?></button></form><a class="btn btn-light" href="messages.php?to=<?=(int)$user['id']?>">Message</a><?php endif;?></div></section>
<?php if($own):?><section class="card edit-profile" id="edit-profile"><h2>Edit RP Profile</h2><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="profile-edit-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>RP Name<input name="display_name" maxlength="80" required value="<?=e($user['display_name'])?>"></label><label>Bio<textarea name="bio" maxlength="500"><?=e($user['bio'])?></textarea></label><label>Profile picture<input type="file" name="avatar" accept="image/*"></label><label>Cover photo<input type="file" name="cover" accept="image/*"></label><button class="btn">Save changes ♡</button></form></section>
<section class="card account-danger" id="delete-account">
<h2>Delete my account</h2>
